import{loadPopularReciters,popularConsentMarkup,bindPopularConsent,personalListening,personalTop,formatListeningTime,listeningDayKey}from './reciter-popularity.js';
import{actionIcon,actionLabel}from './action-icons.js';
import{ruqyahFor,ruqyahMarkup,bindRuqyah}from './quran-ruqyah.js';
import{showListeningScanner}from './quran-listen-share.js';
import{quranDownloadQueue}from './quran-downloads.js';
import{offlineAudioStore}from './quran-offline-store.js';
import{RECITERS,reciterInfo,reciterHasSurah}from './quran-reciters.js';
import{RECITER_FAVORITES_KEY,normalizeReciterFavorites,toggleReciterFavorite}from './quran-reciter-favorites.js';
import{read,write}from './storage.js';
import{esc,toast}from './ui.js';
import{reciterRecording}from './quran-reciter-recording.js';
import{quranPlayback}from './quran-session.js';
const favorites=()=>[...new Set(normalizeReciterFavorites(read(RECITER_FAVORITES_KEY,[]),RECITERS).map(id=>reciterInfo(id).variantOf||id))];
const catalogReciters=RECITERS.filter(r=>!r.variantOf);
export const reciterPortrait=r=>'<img class="reciter-portrait" src="./'+esc(r.portrait||'assets/person.svg')+'" alt="'+esc(r.name)+'" loading="lazy" decoding="async">';
const favoriteButton=(r,saved)=>'<button type="button" class="reciter-favorite" data-reciter-favorite="'+r.id+'" aria-pressed="'+saved.includes(r.id)+'" aria-label="'+(saved.includes(r.id)?'Убрать из избранных: ':'Добавить в избранные: ')+esc(r.name)+'"><img src="./assets/'+(saved.includes(r.id)?'star-fill':'star')+'.svg" alt="" aria-hidden="true"></button>';
export function saveReciterFavorite(id){
 const info=RECITERS.find(r=>r.id===id);if(!info)return false;const next=toggleReciterFavorite(favorites(),info.variantOf||id,RECITERS);if(!next)return false;
 if(!write(RECITER_FAVORITES_KEY,next)){toast('Не удалось сохранить избранного чтеца');return false;}
 window.dispatchEvent(new Event('salah:reciter-favorites'));return true;
}
const card=(r,saved,note='',rank=0)=>'<article class="reciter-card"><a href="#quran?view=reciters&reciter='+encodeURIComponent(r.id)+'">'+(rank?'<span class="reciter-rank" aria-label="Место '+rank+'">'+rank+'</span>':'')+reciterPortrait(r)+'<strong>'+esc(r.name)+'</strong><small>'+(r.availableSurahs?r.availableSurahs.length+' записей':'114 сур')+'</small>'+(note?'<span class="reciter-listening-time" data-personal-time="'+esc(r.id)+'">'+esc(note)+'</span>':'')+'</a>'+favoriteButton(r,saved)+'</article>';
export function quranSectionTabs(active='read'){const reading=active==='read';return '<header class="quran-section-title"><nav class="quran-section-heading" aria-label="Раздел Корана"><div class="quran-heading-read"><a href="#quran" aria-current="'+(reading?'page':'false')+'">'+(reading?'<h1>Коран</h1>':'Коран')+'</a><button type="button" class="button secondary quran-scan-entry" id="quran-open-listening-scanner" aria-label="Сканировать передачу" title="Сканировать QR прослушивания"><svg viewBox="0 0 64 64" aria-hidden="true" focusable="false"><path fill-rule="evenodd" d="M4 4h18v18H4zM7 7h12v12H7zM10 10h6v6H10zM42 4h18v18H42zM45 7h12v12H45zM48 10h6v6H48zM4 42h18v18H4zM7 45h12v12H7zM10 48h6v6H10zM30 8h4v12h-4zM28 28h12v12H28zM46 30h10v6H46zM30 46h6v14h-6zM44 44h8v8h-8zM54 54h6v6h-6z"/></svg></button></div><a href="#quran?view=reciters" aria-current="'+(!reading?'page':'false')+'">'+(!reading?'<h1>Чтецы</h1>':'Чтецы')+'</a></nav><p class="muted">'+(reading?'114 сур':'Выберите голос, который вам близок')+'</p></header>';}
export function mountReciterLibrary(host,index,chosen,filter){
 let renderedDay=listeningDayKey(Date.now());let listeningPeriod=read('reciter-listening-period','day');if(!['day','week','month','all'].includes(listeningPeriod))listeningPeriod='day';let disposeRuqyah=null;let closed=false,request=0,currentQuery='',rankingMode=filter==='salah-top'?'global':'personal',popularIds=null,popularError=false,savedSurahs=new Set();const r=RECITERS.find(r=>r.id===chosen)||null;
 const draw=()=>{renderedDay=listeningDayKey(Date.now());
  disposeRuqyah?.();disposeRuqyah=null;
  const saved=favorites(),selected=saved.map(id=>reciterInfo(id)),others=catalogReciters.filter(r=>!saved.includes(r.id)),favoriteView=filter==='favorites',ruqyahView=filter==='ruqyah',popularView=['popular','my-top','salah-top'].includes(filter);
  host.innerHTML='<section class="quran-library quran-reciters-library">'+quranSectionTabs('reciters')+(r?'<div class="reciter-topnav"><a class="reciter-back-catalog" href="#quran?view=reciters">'+actionLabel('back','Все чтецы')+'</a></div>':'')+(r?
   '<div class="reciter-profile">'+reciterPortrait(r)+'<div><span class="eyebrow">ЧТЕЦ КОРАНА</span><h1>'+esc(r.name)+'</h1><p class="muted">'+(r.availableSurahs?r.availableSurahs.length+' доступных записей':'114 сур')+(r.riwaya?' · '+esc(r.riwaya):'')+'</p>'+favoriteButton(r,saved)+'</div></div>'+ruqyahMarkup(r.id)+(r.offline===false?'<p class="quran-option-note">Этот чтец доступен для прослушивания онлайн. Скачивание пока недоступно.</p>':'')+'<div class="reciter-surahs">'+index.surahs.filter(s=>reciterHasSurah(r.id,s.number)).map(s=>'<article class="reciter-surah-row"><button type="button" data-reciter-play="'+s.number+'"><span class="quran-surah-number">'+s.number+'</span><span><strong>'+esc(s.name)+'</strong><small>'+s.ayahs+' аятов</small></span><span class="reciter-play-label">'+actionLabel('play','Слушать')+'</span></button><button type="button" class="reciter-download" data-reciter-download="'+s.number+'" aria-label="Скачать '+esc(s.name)+' · '+esc(r.name)+'" '+(r.offline===false?'disabled':'')+'>'+(r.offline===false?'Онлайн':actionLabel('download','Скачать'))+'</button></article>').join('')+'</div><p id="reciter-download-status" class="quran-option-note" role="status" aria-live="polite"></p><button type="button" class="text-button" id="reciter-download-pause" hidden>Пауза скачивания</button>':
   '<label class="field">Найти чтеца<input type="search" id="reciter-search" placeholder="Имя чтеца" autocomplete="off"></label><nav class="reciter-filter-tabs" aria-label="Каталог чтецов"><a href="#quran?view=reciters" aria-current="'+(!favoriteView&&!ruqyahView&&!popularView?'page':'false')+'">Все '+catalogReciters.length+'</a><a href="#quran?view=reciters&filter=favorites" aria-current="'+(favoriteView?'page':'false')+'">Избранные '+saved.length+'</a><a href="#quran?view=reciters&filter=ruqyah" aria-current="'+(ruqyahView?'page':'false')+'">Рукъя</a></nav><nav class="reciter-top-tabs" aria-label="Топы чтецов"><a class="reciter-top-tab reciter-top-personal" href="#quran?view=reciters&filter=my-top" aria-current="'+(popularView&&rankingMode==='personal'?'page':'false')+'"><span class="reciter-top-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" aria-hidden="true"><path d="M4 13v-2a8 8 0 0 1 16 0v2M4 12h3v7H4a2 2 0 0 1-2-2v-3a2 2 0 0 1 2-2Zm16 0h-3v7h3a2 2 0 0 0 2-2v-3a2 2 0 0 0-2-2Z"/></svg></span><span><strong>Мой топ</strong><small>Часы и любимые голоса</small></span></a><a class="reciter-top-tab reciter-top-global" href="#quran?view=reciters&filter=salah-top" aria-current="'+(popularView&&rankingMode==='global'?'page':'false')+'"><span class="reciter-top-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M8 3h8v6a4 4 0 0 1-8 0V3Zm0 2H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4m-4 1v5m-4 3h8m-7-3h6"/></svg></span><span><strong>Топ SALAH</strong><small>Выбор сообщества</small></span></a></nav>' +(favoriteView&&!selected.length?'<p class="reciter-empty">Отметьте чтеца звёздочкой — он появится в избранных.</p>':'')+(popularView?''+(rankingMode==='personal'?'<div class="reciter-period-tabs" role="group" aria-label="Период прослушивания">'+[['day','День'],['week','Неделя'],['month','Месяц'],['all','Всё время']].map(([value,label])=>'<button type="button" data-listening-period="'+value+'" aria-pressed="'+(listeningPeriod===value)+'">'+label+'</button>').join('')+'</div><div class="reciter-personal-total"><span>Вы прослушали · '+({day:'сегодня',week:'за неделю',month:'за месяц',all:'всё время'}[listeningPeriod])+'</span><strong>'+formatListeningTime(Object.values(personalListening(listeningPeriod).totals).reduce((sum,n)=>sum+n,0))+'</strong><small>'+(listeningPeriod==='all'?'На этом устройстве':'Счёт по датам — с '+new Intl.DateTimeFormat('ru',{day:'numeric',month:'long'}).format(new Date(personalListening().dailySince)))+'</small></div>'+(!personalTop(listeningPeriod).length?'<p class="reciter-empty">Начните слушать Коран — здесь появится ваш топ чтецов и время прослушивания.</p>':''):'<div class="reciter-popular-heading"><h2>Топ SALAH</h2><p>По минутам прослушивания участников · 30 дней</p></div>'+popularConsentMarkup()+(popularIds===null?'<p class="reciter-empty">'+(popularError?'Рейтинг временно недоступен. Попробуйте позже.':'Загружаем рейтинг…')+'</p>':!popularIds.length?'<p class="reciter-empty">Пока нет учтённых минут. Чтец появится после минуты прослушивания с включённым участием в рейтинге.</p>':'')):'')+'<div class="reciter-grid">'+(popularView?(rankingMode==='personal'?personalTop(listeningPeriod):popularIds||[]).map(id=>reciterInfo(id)):ruqyahView?catalogReciters.filter(item=>ruqyahFor(item.id).length):favoriteView?selected:[...selected,...others]).map((item,i)=>card(item,saved,popularView&&rankingMode==='personal'?formatListeningTime(personalListening(listeningPeriod).totals[item.id]):'',popularView?i+1:0)).join('')+'</div><p id="reciter-search-empty" class="muted" hidden>Чтец не найден</p>')+'<p id="reciter-listen-status" class="quran-option-note" role="status" aria-live="polite"></p></section>';
  disposeRuqyah=bindRuqyah(host);bindPopularConsent(host);host.querySelectorAll('[data-listening-period]').forEach(button=>button.onclick=e=>{listeningPeriod=button.dataset.listeningPeriod;write('reciter-listening-period',listeningPeriod);draw();if(e.detail===0)host.querySelector('[data-listening-period="'+listeningPeriod+'"]')?.focus();});
  host.querySelectorAll('[data-reciter-favorite]').forEach(button=>button.onclick=e=>{const id=button.dataset.reciterFavorite;if(!saveReciterFavorite(id))return;draw();sync(quranPlayback.state);syncDownload(quranDownloadQueue.state);if(e.detail===0)host.querySelector('[data-reciter-favorite="'+id+'"]')?.focus();});
  host.querySelector('#quran-open-listening-scanner').onclick=showListeningScanner;
  const search=host.querySelector('#reciter-search');if(search)search.oninput=()=>{currentQuery=search.value;const q=search.value.toLocaleLowerCase('ru').replace(/ё/g,'е').trim();let count=0;host.querySelectorAll('.reciter-card').forEach(card=>{card.hidden=!card.textContent.toLocaleLowerCase('ru').replace(/ё/g,'е').includes(q);if(!card.hidden)count++;});host.querySelector('#reciter-search-empty').hidden=count>0||!q;};
  if(search){search.value=currentQuery;search.oninput();}
  host.querySelectorAll('[data-reciter-play]').forEach(button=>button.onclick=async()=>{
   const token=++request,number=Number(button.dataset.reciterPlay),status=host.querySelector('#reciter-listen-status');const active=quranPlayback.state;if((active.reciter===r.id||active.reciter===r.continuousReciter)&&active.surah?.number===number&&['playing','paused','loading'].includes(active.status)){quranPlayback.toggle();return;}status.textContent='Загружаем '+index.surahs[number-1].name+'…';
   try{const surah=reciterRecording(index,number);if(closed||token!==request)return;write('quran-preferences',{...read('quran-preferences',{}),reciter:r.id});await quranPlayback.start(surah,r.id,0,true);if(!closed&&token===request)status.textContent='';}catch{if(!closed&&token===request)status.textContent='Не удалось загрузить суру. Проверьте соединение.'}
  });

  host.querySelectorAll('[data-reciter-download]').forEach(button=>button.onclick=()=>{if(!r||r.offline===false)return;if(quranDownloadQueue.busy){toast('Дождитесь завершения текущего скачивания');return;}void quranDownloadQueue.start(r.id,[Number(button.dataset.reciterDownload)]);});
  const pauseDownload=host.querySelector('#reciter-download-pause');if(pauseDownload)pauseDownload.onclick=()=>quranDownloadQueue.pause();
 };
function syncDownload(state){
 if(closed||!r)return;const matches=state.reciter===r.id,busy=quranDownloadQueue.busy;
 if(matches&&state.status==='complete'&&state.done===1&&state.total===1)savedSurahs.add(state.surah);
 host.querySelectorAll('[data-reciter-download]').forEach(button=>{const number=Number(button.dataset.reciterDownload),working=matches&&state.surah===number&&busy;const label=r.offline===false?'Онлайн':working?'Скачиваем…':savedSurahs.has(number)?'Скачать снова':'Скачать';if(button.dataset.downloadLabel!==label){button.innerHTML=r.offline===false?label:actionLabel('download',label);button.dataset.downloadLabel=label;}const disabled=busy||r.offline===false;if(button.disabled!==disabled)button.disabled=disabled;});
 const status=host.querySelector('#reciter-download-status');if(status){const text=matches?(busy?'Скачиваем '+index.surahs[state.surah-1].name+' · '+Math.round((state.bytes+(state.currentBytes||0))/1024)+' КБ':state.status==='complete'?'Сура сохранена для прослушивания без интернета.':state.status==='paused'?'Скачивание приостановлено.':state.status==='error'?state.error:''):busy?'Идёт скачивание другого чтеца.':'';if(status.textContent!==text)status.textContent=text;}
 const pause=host.querySelector('#reciter-download-pause');if(pause)pause.hidden=!matches||!busy;
}
 const sync=state=>{if(closed)return;host.querySelectorAll('[data-reciter-play]').forEach(b=>{const match=state.reciter===r?.id&&state.surah?.number===Number(b.dataset.reciterPlay),playing=match&&['playing','loading'].includes(state.status);b.setAttribute('aria-pressed',String(playing));const label=playing?'Пауза':match&&state.status==='paused'?'Продолжить':'Слушать',control=b.querySelector('.reciter-play-label');if(control.dataset.playLabel!==label){control.innerHTML=actionLabel(playing?'pause':'play',label);control.dataset.playLabel=label;}});};draw();const refreshGlobal=()=>{if(closed||r||filter!=='salah-top'||document.hidden||document.activeElement===host.querySelector('#reciter-search'))return;void loadPopularReciters().then(ids=>{if(closed)return;popularIds=ids;popularError=false;if(document.activeElement!==host.querySelector('#reciter-search'))draw();}).catch(()=>{if(closed)return;popularError=true;draw();});};refreshGlobal();const globalTimer=filter==='salah-top'?setInterval(refreshGlobal,60000):null;const periodTimer=['popular','my-top'].includes(filter)?setInterval(()=>{if(!closed&&!r&&renderedDay!==listeningDayKey(Date.now())&&document.activeElement!==host.querySelector('#reciter-search'))draw();},60000):null;window.addEventListener('salah:popularity-updated',refreshGlobal);document.addEventListener('visibilitychange',refreshGlobal);const refreshConsent=()=>{if(!closed&&!r&&['popular','my-top','salah-top'].includes(filter))draw();};window.addEventListener('salah:counter-status',refreshConsent);const refreshListening=()=>{if(closed||r||!['popular','my-top'].includes(filter))return;if(document.activeElement===host.querySelector('#reciter-search')){const totals=personalListening(listeningPeriod).totals;const heading=host.querySelector('.reciter-personal-total strong');if(heading)heading.textContent=formatListeningTime(Object.values(totals).reduce((sum,n)=>sum+n,0));host.querySelectorAll('[data-personal-time]').forEach(el=>el.textContent=formatListeningTime(totals[el.dataset.personalTime]));}else draw();};window.addEventListener('salah:personal-listening',refreshListening);const unsubscribe=quranPlayback.subscribe(sync);const unsubscribeDownload=quranDownloadQueue.subscribe(syncDownload);if(r)void offlineAudioStore.listRecordings(r.id).then(records=>{if(closed)return;for(const record of records)savedSurahs.add(record.surah);syncDownload(quranDownloadQueue.state);}).catch(()=>{});
 return()=>{closed=true;request++;if(globalTimer)clearInterval(globalTimer);if(periodTimer)clearInterval(periodTimer);window.removeEventListener('salah:popularity-updated',refreshGlobal);document.removeEventListener('visibilitychange',refreshGlobal);window.removeEventListener('salah:counter-status',refreshConsent);window.removeEventListener('salah:personal-listening',refreshListening);disposeRuqyah?.();unsubscribe();unsubscribeDownload();};
}
